  function openPractice(overlay, action, questions) {
    const container = overlay.querySelector('[data-node-id="practice-content"]');
    if (!container) return;
    container.setAttribute('data-dc-practice-content','');
    const choice = name => main.querySelector('input[name="'+name+'"]:checked')?.value || '';
    const category = action.practiceCategory || choice('practice-category'), level = choice('practice-level');
    let pool = questions.filter(q => (!category || category==='すべて' || q.category===category) && (!level || level==='全Level' || level==='Level 0'));
    if (action.practiceMode==='random') {
      for (let i=pool.length-1;i>0;i--) {
        const j=Math.floor(Math.random()*(i+1));
        [pool[i],pool[j]]=[pool[j],pool[i]];
      }
    }
    let index=Math.max(0,pool.findIndex(q=>q.number===action.questionNumber));
    let initialChoice=action.initialChoice;
    const node=(tag,text)=>{const el=document.createElement(tag); if(text!==undefined)el.textContent=text; return el;};
    const button=(text,fn)=>{const el=node('button',text);el.type='button';el.onclick=fn;return el;};
    const show=(...children)=>{container.replaceChildren(...children);container.closest('article')?.scrollTo(0,0);};
    const list=()=>show(node('h2','問題一覧'),...pool.map((q,i)=>button('Q'+q.number+'　'+q.prompt,()=>{index=i;question();})));
    function question(){
      const q=pool[index], selected=new Set();
      const title=node('h2','Q'+q.number+' · '+q.category);
      const prompt=node('p',q.prompt), answers=node('fieldset');
      answers.append(node('legend',q.correct.length>1?'当てはまるものをすべて選択':'ひとつ選択'));
      const grade=button('答え合わせ',()=>finish(false));
      grade.disabled=true;
      q.choices.forEach((value,i)=>{
        const label=node('label'),input=node('input');
        input.type=q.correct.length>1?'checkbox':'radio'; input.name='practice-answer';
        input.onchange=()=>{
          if(input.type==='radio')selected.clear();
          if(input.checked)selected.add(i);else selected.delete(i);
          grade.disabled=!selected.size;
        };
        if(i===initialChoice){input.checked=true;selected.add(i);grade.disabled=false;}
        label.append(input,document.createTextNode(value));answers.append(label);
      });
      initialChoice=undefined;
      function finish(unknown){
        const correct=selected.size===q.correct.length && q.correct.every(i=>selected.has(i));
        const again=button('もう一度解く',question);
        const next= index+1<pool.length ? button('次の問題',()=>{index++;question();}) : button('一覧へ',list);
        show(title,node('h3',unknown?'解説':correct?'正解':'不正解'),node('p','正答　'+q.correct.map(i=>q.choices[i]).join(' ／ ')),node('p',q.explanation),again,next);
      }
      show(title,prompt,answers,grade,button('わからない',()=>finish(true)),button('一覧へ',list));
    }
    if(!pool.length)show(node('p','この条件に該当する問題はありません。'));
    else if(action.practiceMode==='list')list();
    else if(action.practiceMode==='detail'){
      const q=pool[index];show(node('h2','Q'+q.number+' · 問題詳細'),node('p',q.prompt),node('p','正答　'+q.correct.map(i=>q.choices[i]).join(' ／ ')),node('p',q.explanation),button('この問題を解く',question));
    }else question();
  }
