    const inputs = keepInput ? [...main.querySelectorAll('input,textarea,select')].map(el => ({id:el.getAttribute('data-node-id') || el.name, value:el.value, checked:el.checked})) : [];
    main.innerHTML = state.html;
    if (keepInput) for (const el of main.querySelectorAll('input,textarea,select')) {
      const old = inputs.find(v => v.id && v.id === (el.getAttribute('data-node-id') || el.name));
      if (old && el.type !== 'file') { el.value=old.value; if ('checked' in el) el.checked=old.checked; }
    }
